using System;using System.Collections.Generic;using System.Linq;using System.IO;using System.Reflection;using System.Runtime.InteropServices;using System.Runtime.Serialization;using System.Runtime.Serialization.Json;using System.Diagnostics;using System.Windows;using System.Windows.Controls;using System.Windows.Media;using System.Windows.Media.Imaging;using System.Windows.Input;using System.Windows.Threading;
namespace Lumina {
    public static class TaskbarAutoHide {
        [StructLayout(LayoutKind.Sequential)] struct RECT{public int Left,Top,Right,Bottom;}
        [StructLayout(LayoutKind.Sequential)] struct APPBARDATA{public uint Size;public IntPtr Window;public uint Message,Edge;public RECT Rect;public IntPtr Param;}
        [DllImport("shell32.dll")] static extern UIntPtr SHAppBarMessage(uint message,ref APPBARDATA data);
        [DllImport("user32.dll",CharSet=CharSet.Unicode)] static extern IntPtr FindWindow(string cls,string name);
        static string Journal{get{return System.IO.Path.Combine(Store.Folder,"taskbar-autohide.json");}}
        static APPBARDATA Data(){var d=new APPBARDATA{Size=(uint)Marshal.SizeOf(typeof(APPBARDATA)),Window=FindWindow("Shell_TrayWnd",null)};if(d.Window==IntPtr.Zero)throw new InvalidOperationException("未找到 Windows 任务栏");return d;}
        static uint State(){var data=Data();return (uint)SHAppBarMessage(4,ref data).ToUInt64();}
        public static bool Enabled{get{return (State()&1)!=0;}}
        static void Apply(uint state){var data=Data();data.Param=new IntPtr(state);SHAppBarMessage(10,ref data);if((State()&1)!=(state&1))throw new InvalidOperationException("Windows 尚未确认任务栏自动隐藏状态，恢复记录已保留。");}
        public static void Set(bool enabled){uint state=State();if(((state&1)!=0)==enabled)return;Directory.CreateDirectory(Store.Folder);if(!File.Exists(Journal))File.WriteAllText(Journal,state.ToString(System.Globalization.CultureInfo.InvariantCulture));Apply(FeatureRules.AutoHideState(state,enabled));}
        public static void Restore(){if(!File.Exists(Journal))return;uint original=uint.Parse(File.ReadAllText(Journal),System.Globalization.CultureInfo.InvariantCulture);Apply(FeatureRules.AutoHideState(State(),(original&1)!=0));File.Delete(Journal);}
        public static void ShowAndClear(){Apply(FeatureRules.AutoHideState(State(),false));if(File.Exists(Journal))File.Delete(Journal);}
    }
    public static class FeatureUi {
        public static string PickFolder(Window window,string description){using(var dialog=new System.Windows.Forms.FolderBrowserDialog{Description=description,ShowNewFolderButton=false}){var owner=new System.Windows.Forms.NativeWindow();owner.AssignHandle(new System.Windows.Interop.WindowInteropHelper(window).EnsureHandle());try{return dialog.ShowDialog(owner)==System.Windows.Forms.DialogResult.OK?dialog.SelectedPath:null;}finally{owner.ReleaseHandle();}}}
        public static HotkeySetting Record(Window owner,int action){var w=Dialog("录制快捷键",owner,480,230);var stack=new StackPanel{Margin=new Thickness(24)};w.Content=stack;stack.Children.Add(new TextBlock{Text="按下一组快捷键",FontSize=22,Margin=new Thickness(0,0,0,16)});var hint=new TextBlock{Text="需要 Ctrl / Alt / Shift，搭配字母、数字、功能键等。\nEsc 取消；占用情况会在保存时检查。",TextWrapping=TextWrapping.Wrap};stack.Children.Add(hint);HotkeySetting captured=null;w.PreviewKeyDown+=(s,e)=>{e.Handled=true;var key=e.Key==Key.System?e.SystemKey:e.Key;if(key==Key.Escape){w.Close();return;}if(captured!=null)return;if(key==Key.LeftCtrl||key==Key.RightCtrl||key==Key.LeftAlt||key==Key.RightAlt||key==Key.LeftShift||key==Key.RightShift)return;uint modifiers=(uint)Keyboard.Modifiers;uint value=(uint)KeyInterop.VirtualKeyFromKey(key);if(!HotkeyRules.ModifierValues.Contains(modifiers)||!HotkeyRules.Keys().ContainsValue(value)){hint.Text="不支持这组按键，请使用列表支持的组合。";return;}captured=new HotkeySetting{ActionId=action,Modifiers=modifiers,Key=value,Enabled=true};hint.Text="已录制："+HotkeyRules.Label(captured)+"\n释放按键完成录制。";};w.PreviewKeyUp+=(s,e)=>{e.Handled=true;if(captured!=null&&Keyboard.Modifiers==ModifierKeys.None&&!Keyboard.IsKeyDown(KeyInterop.KeyFromVirtualKey((int)captured.Key)))w.DialogResult=true;};w.ShowDialog();return w.DialogResult==true?captured:null;}
        public static Window Dialog(string title,Window owner,double width=650,double height=560){var w=new Window{Title="Lumina · "+title,Owner=owner,Width=Math.Min(width,SystemParameters.WorkArea.Width-40),Height=Math.Min(height,SystemParameters.WorkArea.Height-50),WindowStartupLocation=WindowStartupLocation.CenterOwner,Background=new SolidColorBrush(Color.FromRgb(30,33,42)),Foreground=Brushes.White,Topmost=true};Polish.Apply(w,false);return w;}
        public static Button Button(string text,Action action){var button=new Button{Content=text,Padding=new Thickness(12,7,12,7),Margin=new Thickness(0,0,8,8)};button.Click+=(s,e)=>action();return button;}
        public static string Ask(Window owner,string title,string value=""){var w=Dialog(title,owner,440,180);var stack=new StackPanel{Margin=new Thickness(22)};w.Content=stack;var text=new TextBox{Text=value,MinHeight=38,FontSize=14};stack.Children.Add(text);string result=null;var apply=Button("确定",()=>{if(!string.IsNullOrWhiteSpace(text.Text)){result=text.Text.Trim();w.DialogResult=true;}});apply.Margin=new Thickness(0,18,0,0);stack.Children.Add(apply);w.Loaded+=(s,e)=>{text.Focus();text.SelectAll();};text.KeyDown+=(s,e)=>{if(e.Key==Key.Enter)apply.RaiseEvent(new RoutedEventArgs(System.Windows.Controls.Button.ClickEvent));};w.ShowDialog();return result;}
        public static string StoreIcon(string path){Directory.CreateDirectory(System.IO.Path.Combine(Store.Folder,"icons"));var image=new BitmapImage();image.BeginInit();image.CacheOption=BitmapCacheOption.OnLoad;image.UriSource=new Uri(path);image.DecodePixelWidth=128;image.EndInit();image.Freeze();var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(image));string saved=System.IO.Path.Combine(Store.Folder,"icons",Guid.NewGuid().ToString("N")+".png");using(var s=File.Create(saved))encoder.Save(s);return saved;}
        static readonly BoundedCache<string,ImageSource> customIconCache=new BoundedCache<string,ImageSource>(128,StringComparer.OrdinalIgnoreCase);
        public static ImageSource Icon(Entry entry,bool showShortcutOverlays=false,bool sharper=false){if(!string.IsNullOrWhiteSpace(entry.IconPath)&&File.Exists(entry.IconPath)){try{var info=new FileInfo(entry.IconPath);string key=info.FullName+"/"+info.Length+"/"+info.LastWriteTimeUtc.Ticks;ImageSource cached;if(customIconCache.TryGet(key,out cached))return cached;var image=new BitmapImage();image.BeginInit();image.CacheOption=BitmapCacheOption.OnLoad;image.UriSource=new Uri(entry.IconPath);image.DecodePixelWidth=128;image.EndInit();image.Freeze();customIconCache.Put(key,image);return image;}catch{}}var icon=Native.Icon(entry.Path,showShortcutOverlays,sharper);if(icon!=null)return icon;if(entry.IsFolder||Directory.Exists(entry.Path)){var drawing=new GeometryDrawing(new SolidColorBrush(Color.FromRgb(240,191,77)),new Pen(new SolidColorBrush(Color.FromRgb(204,149,45)),1),Geometry.Parse("M 2,5 L 8,5 L 10,7 L 18,7 L 18,17 L 2,17 Z"));var image=new DrawingImage(drawing);image.Freeze();return image;}return null;}
    }
    public static class SchemeStore {
        public static string Folder{get{return System.IO.Path.Combine(Store.Folder,"schemes");}}
        public static string[] Files(){Directory.CreateDirectory(Folder);return Directory.GetFiles(Folder,"*.json");}
        public static AppearanceScheme Load(string path){if(new FileInfo(path).Length>5*1024*1024)throw new InvalidDataException("方案文件超过 5 MB");using(var s=File.OpenRead(path)){var data=(AppearanceScheme)new DataContractJsonSerializer(typeof(AppearanceScheme)).ReadObject(s);if(data==null||data.Version!=1||data.Dock==null)throw new InvalidDataException("方案格式不支持");return data;}}
        public static void Save(AppearanceScheme data,string path){using(var s=File.Create(path))new DataContractJsonSerializer(typeof(AppearanceScheme)).WriteObject(s,data);}
        public static void Embed(AppearanceScheme data){data.Icons=new Dictionary<string,string>();int index=0;foreach(var entry in data.Apps.Where(a=>!string.IsNullOrWhiteSpace(a.IconPath)&&File.Exists(a.IconPath))){var bytes=File.ReadAllBytes(entry.IconPath);if(bytes.Length>512*1024)continue;string key="icon-"+(index++)+".png";data.Icons[key]=Convert.ToBase64String(bytes);entry.IconPath="[asset]"+key;}}
        public static void Materialize(AppearanceScheme data){if(data.Icons==null)data.Icons=new Dictionary<string,string>();foreach(var entry in (data.Apps??new List<Entry>()).Where(a=>a!=null&&a.IconPath!=null&&a.IconPath.StartsWith("[asset]",StringComparison.Ordinal))){string encoded;if(!data.Icons.TryGetValue(entry.IconPath.Substring(7),out encoded)||encoded.Length>700000){entry.IconPath=null;continue;}byte[] bytes=Convert.FromBase64String(encoded);if(bytes.Length>512*1024)throw new InvalidDataException("方案图标过大");Directory.CreateDirectory(System.IO.Path.Combine(Store.Folder,"icons"));string path=System.IO.Path.Combine(Store.Folder,"icons",Guid.NewGuid().ToString("N")+".png");File.WriteAllBytes(path,bytes);entry.IconPath=path;}}
    }
}
